"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

_ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}
_MOVES = ((0, 1), (1, 0), (0, -1), (-1, 0))  # right, down, left, up


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    if not grid or not grid[0]:
        raise ValueError(f"grid must be non-empty, got {grid!r}")

    width = len(grid[0])
    start: Cell | None = None
    goal: Cell | None = None

    for row, line in enumerate(grid):
        if len(line) != width:
            raise ValueError(f"grid rows must have equal length, got {grid!r}")
        for col, tile in enumerate(line):
            if tile not in _ENTER_COST and tile != "#":
                raise ValueError(f"unknown tile {tile!r} at {(row, col)}")
            if tile == "S":
                if start is not None:
                    raise ValueError(f"grid has multiple 'S' cells: {grid!r}")
                start = (row, col)
            elif tile == "G":
                if goal is not None:
                    raise ValueError(f"grid has multiple 'G' cells: {grid!r}")
                goal = (row, col)

    if start is None or goal is None:
        raise ValueError(f"grid must contain one 'S' and one 'G', got {grid!r}")

    # Best known (cost, steps, path) for each cell. Cost is primary so a cheap
    # door route beats a shorter but expensive one; steps and the path tuple
    # only break ties to keep the result deterministic.
    best: dict[Cell, tuple[int, int, tuple[Cell, ...]]] = {
        start: (0, 0, (start,))
    }
    queue: list[tuple[int, int, tuple[Cell, ...], Cell]] = [
        (0, 0, (start,), start)
    ]

    while queue:
        cost, steps, path, cell = heapq.heappop(queue)
        if best.get(cell) != (cost, steps, path):
            continue
        if cell == goal:
            return list(path)

        row, col = cell
        for drow, dcol in _MOVES:
            nxt = (row + drow, col + dcol)
            nrow, ncol = nxt
            if not (0 <= nrow < len(grid) and 0 <= ncol < width):
                continue
            tile = grid[nrow][ncol]
            if tile == "#":
                continue
            candidate = (cost + _ENTER_COST[tile], steps + 1, path + (nxt,))
            if nxt not in best or candidate < best[nxt]:
                best[nxt] = candidate
                heapq.heappush(
                    queue, (candidate[0], candidate[1], candidate[2], nxt)
                )

    return None
